def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    tokens_re = re.compile(
        r'\s*(<=|>=|<>|[()+\-*/,:=<>]|[A-Z](?:[1-9]\d?)|[0-9]+|[A-Za-z]+)'
    )

    def tokenize(text):
        tokens = []
        pos = 0
        while pos < len(text):
            match = tokens_re.match(text, pos)
            if not match:
                raise ValueError("Invalid formula")
            tokens.append(match.group(1))
            pos = match.end()
        return tokens

    parsed = {}
    states = {}  # 0 = unseen, 1 = evaluating, 2 = evaluated
    values = {}

    def parse_cell(name):
        if name in parsed:
            return parsed[name]
        content = cells[name]
        if not content.startswith("="):
            parsed[name] = ("literal", int(content))
        else:
            parser = Parser(tokenize(content[1:]))
            parsed[name] = parser.parse()
        return parsed[name]

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.i = 0

        def peek(self):
            return self.tokens[self.i] if self.i < len(self.tokens) else None

        def take(self):
            token = self.peek()
            self.i += 1
            return token

        def expression(self):
            node = self.term()
            while self.peek() in ("+", "-"):
                op = self.take()
                node = ("binary", op, node, self.term())
            return node

        def term(self):
            node = self.unary()
            while self.peek() in ("*", "/"):
                op = self.take()
                node = ("binary", op, node, self.unary())
            return node

        def unary(self):
            if self.peek() == "-":
                self.take()
                return ("neg", self.unary())
            return self.atom()

        def atom(self):
            token = self.take()
            if token == "(":
                node = self.expression()
                self.take()  # )
                return node
            if token is None:
                raise ValueError("Unexpected end")
            if token.isdigit():
                return ("number", int(token))
            if re.fullmatch(r"[A-Z](?:[1-9]\d?)", token):
                return ("cell", token)
            if token in ("SUM", "MIN", "MAX"):
                self.take()  # (
                args = []
                while True:
                    args.append(self.function_arg())
                    if self.peek() == ",":
                        self.take()
                        continue
                    self.take()  # )
                    break
                return ("aggregate", token, args)
            if token == "IF":
                self.take()  # (
                left = self.expression()
                op = self.take()
                right = self.expression()
                self.take()  # ,
                then_expr = self.expression()
                self.take()  # ,
                else_expr = self.expression()
                self.take()  # )
                return ("if", left, op, right, then_expr, else_expr)
            raise ValueError("Invalid atom")

        def function_arg(self):
            # A range is recognized as a cell token followed by ':' and another cell.
            if (self.i + 2 < len(self.tokens)
                    and re.fullmatch(r"[A-Z](?:[1-9]\d?)", self.tokens[self.i])
                    and self.tokens[self.i + 1] == ":"
                    and re.fullmatch(r"[A-Z](?:[1-9]\d?)", self.tokens[self.i + 2])):
                first = self.take()
                self.take()
                second = self.take()
                return ("range", first, second)
            return ("formula", self.expression())

    def evaluate_cell(name):
        if name not in cells:
            return 0
        state = states.get(name, 0)
        if state == 1:
            return "#CYCLE!"
        if state == 2:
            return values[name]

        states[name] = 1
        result = evaluate(parse_cell(name))
        values[name] = result
        states[name] = 2
        return result

    def evaluate(node):
        kind = node[0]
        if kind == "literal" or kind == "number":
            return node[1]
        if kind == "cell":
            return evaluate_cell(node[1])
        if kind == "neg":
            value = evaluate(node[1])
            return value if isinstance(value, str) else -value
        if kind == "binary":
            _, op, left_node, right_node = node
            left = evaluate(left_node)
            if isinstance(left, str):
                return left
            right = evaluate(right_node)
            if isinstance(right, str):
                return right
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if kind == "if":
            _, left_node, op, right_node, then_node, else_node = node
            left = evaluate(left_node)
            if isinstance(left, str):
                return left
            right = evaluate(right_node)
            if isinstance(right, str):
                return right
            condition = {
                "=": left == right,
                "<>": left != right,
                "<": left < right,
                "<=": left <= right,
                ">": left > right,
                ">=": left >= right,
            }[op]
            return evaluate(then_node if condition else else_node)
        if kind == "aggregate":
            _, function, args = node
            result = None
            for arg in args:
                if arg[0] == "formula":
                    items = (evaluate(arg[1]),)
                else:
                    _, first, second = arg
                    col1, row1 = ord(first[0]) - 65, int(first[1:])
                    col2, row2 = ord(second[0]) - 65, int(second[1:])
                    items = (
                        evaluate_cell(chr(col + 65) + str(row))
                        for row in range(min(row1, row2), max(row1, row2) + 1)
                        for col in range(min(col1, col2), max(col1, col2) + 1)
                        if chr(col + 65) + str(row) in cells
                    )
                for value in items:
                    if isinstance(value, str):
                        return value
                    if result is None:
                        result = value
                    elif function == "SUM":
                        result += value
                    elif function == "MIN":
                        result = min(result, value)
                    else:
                        result = max(result, value)
            return 0 if result is None else result
        raise ValueError("Invalid node")

    result = {}
    for name in cells:
        result[name] = evaluate_cell(name)
    return result
